{
  "technical_and_design_decisions": [
    "Implement in Go, consistent with the Hyperledger Fabric codebase, extending the existing channel configuration (configtx-style) library rather than creating a new module.",
    "All modification functions will operate on a standard protobuf Config/ConfigGroup tree (cb.Config), navigating ChannelGroup -> orderer/application org groups -> Values, and will preserve all untouched fields so a ConfigUpdate can be computed afterward with the existing ComputeUpdate tooling.",
    "For U1/U2, implement AddOrdererEndpoint and RemoveOrdererEndpoint functions that mutate the Endpoints value inside a named orderer org's config group.",
    "For U3, implement a single GetPolicies-style retrieval that resolves the org group path differently for application, orderer, and consortium orgs, returning the policy map without manual parsing by the caller.",
    "For U4, introduce a config.Capabilities wrapper type aggregating channel, orderer, and application capabilities retrieved from the respective Capability values.",
    "For U5, implement generic Add/Remove capability functions keyed by capability string for each of channel, orderer, and application scopes (rather than hard-coded toggle functions), since generic setters also satisfy the toggle use case and support future capabilities; known-capability constants will be provided for convenience.",
    "For U6, define a config.Application struct (organizations, capabilities, ACLs, policies) populated from the application group of the config transaction.",
    "For U7, implement AddACL and RemoveACL functions mutating the ACLs value of the application group, re-serializing via protolator-compatible marshaling.",
    "Use table-driven unit tests with existing sample channel config block fixtures; example tests written as Go Example functions for U8's split scenarios (orderer config, application values, org management, MSP, capabilities)."
  ],
  "assumptions": [
    "An existing library codebase is in place with Config/ConfigUpdate computation utilities and test fixtures; this increment adds functions to it (no greenfield setup).",
    "The developer is proficient in Go and already familiar with Fabric channel config protobuf structures; only modest design/analysis ramp-up is needed.",
    "Estimates include implementation, unit tests, and example test updates; they exclude CI pipeline setup, release packaging, and deployment.",
    "No changes to Fabric core (peer/orderer binaries) are required; this is a client-side configuration library increment.",
    "Sample channel config blocks covering orderer orgs, application orgs, consortiums, capabilities, ACLs, and MSP are available from existing test utilities.",
    "Code review feedback rework is included; the reviewer's own time is excluded since the developer performs all work alone.",
    "Where the spec is ambiguous (U5 toggle vs. generic setters), the generic approach above is assumed and no further clarification is needed."
  ],
  "activities": [
    {
      "activity_id": "A1",
      "activity_name": "Requirements analysis and API design",
      "activity_description": "Analyze U1-U8, inspect the existing codebase, define function signatures and new types (config.Capabilities, config.Application), and decide the generic capability setter approach for U5.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A2",
      "activity_name": "U1: Add orderer endpoint",
      "activity_description": "Implement function to add an orderer endpoint to an orderer org's config group, with unit tests and a demonstration snippet for the example test.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A3",
      "activity_name": "U2: Remove orderer endpoint",
      "activity_description": "Implement function to remove an orderer endpoint from an orderer org's config group, with unit tests and a demonstration snippet (reuses U1 patterns).",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A4",
      "activity_name": "U3: Retrieve org policies",
      "activity_description": "Implement policy retrieval for a specific org covering application, orderer, and consortium org group paths; unit tests and example test update.",
      "most_likely_effort": 8
    },
    {
      "activity_id": "A5",
      "activity_name": "U4: Retrieve capabilities",
      "activity_description": "Implement retrieval of channel, orderer, and application capabilities from a config transaction returning a config.Capabilities value, with unit tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A6",
      "activity_name": "U5: Add/remove capabilities",
      "activity_description": "Implement add and remove capability functions for application, orderer, and channel scopes (six functions) plus known-capability constants; unit tests and example test update.",
      "most_likely_effort": 10
    },
    {
      "activity_id": "A7",
      "activity_name": "U6: Retrieve application configuration",
      "activity_description": "Implement retrieval of the full application group configuration returning a config.Application (orgs, ACLs, policies, capabilities), with unit tests.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A8",
      "activity_name": "U7: Add/remove application ACLs",
      "activity_description": "Implement functions to add and remove ACL entries in the application group's ACLs value; unit tests and example test update.",
      "most_likely_effort": 6
    },
    {
      "activity_id": "A9",
      "activity_name": "U8: Restructure example tests",
      "activity_description": "Split the single end-to-end example into focused examples: orderer configuration (with orderer policies), application values (with application policies), organization management (orgs, anchor peers, orderer endpoints), MSP modifications, and capabilities; integrate U1-U3/U5/U7 demonstrations.",
      "most_likely_effort": 12
    },
    {
      "activity_id": "A10",
      "activity_name": "Documentation",
      "activity_description": "Write godoc comments for all new exported functions and types, and update README/package documentation with the new capabilities.",
      "most_likely_effort": 4
    },
    {
      "activity_id": "A11",
      "activity_name": "Integration, self-review, and rework",
      "activity_description": "Run full test suites, verify ConfigUpdate computation works end-to-end on modified configs (acceptance criteria), self-review code, and apply rework/fixes.",
      "most_likely_effort": 6
    }
  ],
  "reported_total": {
    "most_likely_effort": 76
  }
}

